package com.example.rokidkeyboardbridge;
import android.content.*;import android.util.AtomicFile;import org.json.*;import java.io.*;
/** One encrypted, read-only route snapshot. Never resumes navigation or supplies live cues. */
public final class NavigationPocketRoute {
 private String signature="";
 static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"navigation-pocket-route.gcm"));}
 public static JSONObject snapshot(JSONObject packet,long now)throws Exception{if(!packet.optBoolean("navigationActive")||!packet.optBoolean("routeReady")||packet.optBoolean("suppressed")||packet.optBoolean("routeRefreshing")||packet.optBoolean("guidancePaused"))throw new IOException("保存できる確定経路がありません");String destination=packet.optString("routeDestination");if(destination.isEmpty()||destination.length()>300)throw new IOException("案内先を確認してください");JSONObject out=new JSONObject().put("destination",destination).put("mode",packet.optString("routeMode")).put("savedAt",now);JSONObject journey=packet.optJSONObject("journey");JSONArray items=journey==null?null:journey.optJSONArray("plannedSteps"),safe=new JSONArray();if(items!=null)for(int i=0;i<Math.min(80,items.length());i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;JSONObject row=new JSONObject();for(String key:new String[]{"travelMode","instruction","departureStop","arrivalStop","lineName","departureTime","arrivalTime"}){String v=item.optString(key);if(v.length()>400)v=v.substring(0,400);row.put(key,v);}JSONObject details=item.optJSONObject("transitDetails");if(details!=null)row.put("headsign",details.optString("headsign").substring(0,Math.min(160,details.optString("headsign").length())));safe.put(row);}out.put("providerFetchedAt",journey==null?0:journey.optLong("fetchedAt",0));out.put("steps",safe);if(safe.length()==0){out.put("referenceInstruction",packet.optString("instruction").substring(0,Math.min(400,packet.optString("instruction").length())));}JSONArray route=packet.optJSONArray("route");if((route==null||route.length()<2)&&journey!=null)route=journey.optJSONArray("wholeRoute");if(route!=null&&route.toString().length()<=400000)out.put("route",new JSONArray(route.toString()));if(out.toString().length()>450000)throw new IOException("経路が大きすぎます");return out;}
 public static boolean enabled(Context c){return c.getSharedPreferences("navigation_pocket_controls",0).getBoolean("enabled",true);}
 public static void enable(Context c){c.getSharedPreferences("navigation_pocket_controls",0).edit().putBoolean("enabled",true).commit();}
 public synchronized boolean capture(Context c,JSONObject packet,long now)throws Exception{if(!enabled(c))return false;String key=packet.optString("routeDestination")+"|"+packet.optString("routeMode")+"|"+packet.optLong("routeGeneration")+"|"+packet.optLong("routeTime")+"|"+packet.optString("phase");if(key.equals(signature))return false;JSONObject value=snapshot(packet,now);byte[] bytes=DeviceSecrets.photos().encrypt(value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));AtomicFile f=file(c);FileOutputStream stream=null;try{stream=f.startWrite();stream.write(bytes);f.finishWrite(stream);signature=key;return true;}catch(Exception e){if(stream!=null)f.failWrite(stream);throw e;}}
 public static JSONObject read(Context c)throws Exception{AtomicFile f=file(c);if(!f.getBaseFile().exists()&&!new File(f.getBaseFile()+".bak").exists())throw new IOException("保存された経路はありません");byte[] bytes=f.readFully();if(bytes.length>500000)throw new IOException("保存経路を確認できません");return new JSONObject(new String(DeviceSecrets.photos().decrypt(bytes),java.nio.charset.StandardCharsets.UTF_8));}
 public synchronized void clear(Context c){file(c).delete();signature="";c.getSharedPreferences("navigation_pocket_controls",0).edit().putBoolean("enabled",false).commit();}
 public static String text(JSONObject saved){long at=saved.optLong("savedAt");String time=at>0?new java.text.SimpleDateFormat("M/d HH:mm",java.util.Locale.JAPAN).format(new java.util.Date(at)):"不明";long fetched=saved.optLong("providerFetchedAt");String fetchedTime=fetched>0?new java.text.SimpleDateFormat("M/d HH:mm",java.util.Locale.JAPAN).format(new java.util.Date(fetched)):"未取得";StringBuilder out=new StringBuilder("保存済み経路（閲覧専用）\n経路取得時刻："+fetchedTime+"\n保存時刻："+time+"\n案内先："+saved.optString("destination")+"\n現在地・遅延・運休・通行可否は未確認です。再検索には通信が必要です。自動再開しません。\n");JSONArray rows=saved.optJSONArray("steps");for(int i=0;rows!=null&&i<rows.length();i++){JSONObject row=rows.optJSONObject(i);out.append(i+1).append(". ").append(row.optString("lineName")).append(' ').append(row.optString("departureStop")).append(row.optString("arrivalStop").isEmpty()?"":" → "+row.optString("arrivalStop")).append(' ').append(row.optString("headsign").isEmpty()?"":"行き先："+row.optString("headsign")).append(' ').append(row.optString("instruction")).append('\n');}if(rows==null||rows.length()==0)out.append("保存時の参考表示：").append(saved.optString("referenceInstruction")).append("\n区間詳細は取得されていません。");return out.toString();}
 public void show(android.app.Activity host){try{JSONObject saved=read(host);android.widget.LinearLayout body=new android.widget.LinearLayout(host);body.setOrientation(1);android.widget.TextView text=new android.widget.TextView(host);text.setText(text(saved));body.addView(text);JSONArray points=saved.optJSONArray("route");if(points!=null&&points.length()>=2){android.widget.TextView legend=new android.widget.TextView(host);legend.setText("保存経路の概略線（地図・現在地表示ではありません）");body.addView(legend);android.view.View shape=new android.view.View(host){protected void onDraw(android.graphics.Canvas canvas){super.onDraw(canvas);android.graphics.Paint pen=new android.graphics.Paint(3);pen.setColor(android.graphics.Color.GREEN);pen.setStrokeWidth(4);pen.setStyle(android.graphics.Paint.Style.STROKE);double minX=Double.POSITIVE_INFINITY,maxX=Double.NEGATIVE_INFINITY,minY=Double.POSITIVE_INFINITY,maxY=Double.NEGATIVE_INFINITY;for(int i=0;i<points.length();i++){JSONArray pair=points.optJSONArray(i);if(pair==null||pair.length()<2)continue;double y=pair.optDouble(0),x=pair.optDouble(1);if(!Double.isFinite(x)||!Double.isFinite(y))continue;minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);}if(!Double.isFinite(minX)||!Double.isFinite(minY))return;android.graphics.Path path=new android.graphics.Path();boolean first=true;double scale=Math.min((getWidth()-24)/Math.max(.00001,maxX-minX),(getHeight()-24)/Math.max(.00001,maxY-minY));for(int i=0;i<points.length();i++){JSONArray pair=points.optJSONArray(i);if(pair==null)continue;double y=pair.optDouble(0),x=pair.optDouble(1);if(!Double.isFinite(x)||!Double.isFinite(y))continue;float px=(float)(12+(x-minX)*scale),py=(float)(getHeight()-12-(y-minY)*scale);if(first){path.moveTo(px,py);first=false;}else path.lineTo(px,py);}canvas.drawPath(path,pen);}};body.addView(shape,new android.widget.LinearLayout.LayoutParams(-1,(int)(180*host.getResources().getDisplayMetrics().density)));}android.widget.ScrollView scroll=new android.widget.ScrollView(host);scroll.addView(body);new android.app.AlertDialog.Builder(host).setTitle("保存経路を確認（閲覧専用）").setView(scroll).setPositiveButton("閉じる",null).setNeutralButton("この端末の保存経路を削除",(d,w)->new android.app.AlertDialog.Builder(host).setMessage("この端末の最後の保存経路を削除し、以後の経路保存を停止しますか？ 現在の案内や保存ルートの登録は変更しません。再度有効にするには保存経路画面を開いて選択してください。").setPositiveButton("削除",(a,k)->clear(host)).setNegativeButton("戻る",null).show()).show();}catch(Exception e){new android.app.AlertDialog.Builder(host).setMessage("保存経路を開けません："+e.getMessage()+"\n今後の経路保存："+(enabled(host)?"有効":"停止中")).setPositiveButton("閉じる",null).setNeutralButton("今後の保存を有効にする",(d,w)->enable(host)).show();}}
 private static final String TAG="NavigationPocketRoute";
}
